SET NAMES utf8mb4;
UPDATE pro_pet.pet SET content = '<p>大家好呀，我是miumiu，一只美国短毛猫小姑娘。我的毛色是漂亮的银灰色虎斑，眼睛圆圆的，性格温柔又粘人。刚见面时我可能会有点害羞，但只要给我一点时间，我就会用软软的脑袋蹭蹭你的手。</p><p>我最喜欢窝在窗边的软垫上晒太阳，也喜欢用尾巴轻轻勾住你的手腕撒娇。熟悉之后，我会在你身边呼噜呼噜地打滚，陪你看书、追剧、发呆——只要你愿意，我就是你家里最贴心的小室友。</p><p>如果你愿意给我一个家，我会用一辈子的陪伴来回应你。希望未来的铲屎官，能给我满满的爱和耐心哦～</p>' WHERE id = 5;
